import{_ as l,r as e,o as r,c,e as a,a as s,s as t}from"./chunks/framework.CXcwiNg-.js";const m=JSON.parse('{"title":"Filter Scopes - October CMS - 4.x","titleTemplate":false,"description":"Learn how to filter lists using scopes.","frontmatter":{"subtitle":"Learn how to filter lists using scopes."},"headers":[{"level":2,"title":"Available Scopes","slug":"available-scopes","link":"#available-scopes","children":[]},{"level":2,"title":"Scope Properties","slug":"scope-properties","link":"#scope-properties","children":[{"level":3,"title":"Applying Model Scopes","slug":"applying-model-scopes","link":"#applying-model-scopes","children":[]},{"level":3,"title":"Scope Dependencies","slug":"scope-dependencies","link":"#scope-dependencies","children":[]}]}],"relativePath":"4.x/element/filter-scopes.md","filePath":"4.x/element/filter-scopes.md"}'),i={name:"4.x/element/filter-scopes.md"};function d(u,n,k,h,g,y){const o=e("pre-heading"),p=e("post-heading");return r(),c("div",null,[a(o),n[0]||(n[0]=s("h1",null,"Filter Scopes",-1)),a(p),n[1]||(n[1]=t(`<p>Filter Scopes are scope definitions used by filters, often in conjunction with a list. Similar to list columns these are referenced by the following areas:</p><ul><li><a href="./../extend/lists/list-controller.html">Backend List Controller</a></li><li><a href="./../extend/forms/relation-controller.html">Backend Relation Controller</a></li></ul><p>All filter scopes are identified as their individual <strong>type</strong> property.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">scopes</span><span class="token punctuation">:</span>
    <span class="token key atrule">myscope</span><span class="token punctuation">:</span>
        <span class="token key atrule">type</span><span class="token punctuation">:</span> date
        <span class="token comment"># ...</span>
</code></pre></div><h2 id="available-scopes"><a href="#available-scopes" class="header-anchor">#</a> Available Scopes</h2><p>The following filter scopes are available:</p>`,6)),n[2]||(n[2]=s("div",{class:"content-list-p",markdown:"1"},[s("p",null,[s("a",{href:"./filter/scope-checkbox.html"},"Checkbox"),s("a",{href:"./filter/scope-switch.html"},"Switch"),s("a",{href:"./filter/scope-text.html"},"Text"),s("a",{href:"./filter/scope-number.html"},"Number"),s("a",{href:"./filter/scope-dropdown.html"},"Dropdown"),s("a",{href:"./filter/scope-group.html"},"Group"),s("a",{href:"./filter/scope-date.html"},"Date")])],-1)),n[3]||(n[3]=t(`<h2 id="scope-properties"><a href="#scope-properties" class="header-anchor">#</a> Scope Properties</h2><p>For each scope you can specify these properties (where applicable).</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>a name when displaying the filter scope to the user.</td></tr><tr><td><strong>type</strong></td><td>defines how this scope should be displayed. Default: <code>group</code>.</td></tr><tr><td><strong>conditions</strong></td><td>enables or disables condition functions or specifies a raw where query statement to apply to each condition, see the scope type definition for details.</td></tr><tr><td><strong>modelClass</strong></td><td>class of the model to use as a data source and reference for local method calls.</td></tr><tr><td><strong>modelScope</strong></td><td>specifies a <a href="./../extend/database/model.html">model query scope</a> method defined in the <strong>list model</strong> to apply to the list query. The first argument will contain the query object (as per a regular scope method) and the second argument will contain the scope definition, including its populated value(s).</td></tr><tr><td><strong>options</strong></td><td>options to use if filtering by multiple items, supplied as an array.</td></tr><tr><td><strong>optionsMethod</strong></td><td>request options from a method name defined on the model or as a static method call, eg <code>Class::method</code>.</td></tr><tr><td><strong>emptyOption</strong></td><td>an optional label for an intentional empty selection.</td></tr><tr><td><strong>default</strong></td><td>supply a default value for the filter, as either array, string or integer depending on the filter value.</td></tr><tr><td><strong>permissions</strong></td><td>the <a href="./../extend/backend/permissions.html">permissions</a> that the current backend user must have in order for the filter scope to be used. Supports either a string for a single permission or an array of permissions of which only one is needed to grant access.</td></tr><tr><td><strong>dependsOn</strong></td><td>a string or an array of other scope names that this scope depends on. When the other scopes are modified, this scope will reset.</td></tr><tr><td><strong>nameFrom</strong></td><td>a model attribute name used for displaying the filter label. Default: <code>name</code>.</td></tr><tr><td><strong>valueFrom</strong></td><td>defines a model attribute to use for the source value. Default comes from the scope name.</td></tr><tr><td><strong>order</strong></td><td>a numerical weight when determining the display order, default value increments at 100 points per scope.</td></tr><tr><td><strong>after</strong></td><td>place this scope after another existing scope name using the display order (+1).</td></tr><tr><td><strong>before</strong></td><td>place this scope before another existing scope name using the display order (-1).</td></tr></tbody></table></div><h3 id="applying-model-scopes"><a href="#applying-model-scopes" class="header-anchor">#</a> Applying Model Scopes</h3><p>Most filters will apply their scoped constraints using sensible defaults. The <code>modelScope</code> property can be used to apply custom constraints to the filter query using a <a href="./../extend/database/model.html">model scope method definition</a>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">myfilter</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> My Filter
    <span class="token key atrule">type</span><span class="token punctuation">:</span> group
    <span class="token key atrule">modelScope</span><span class="token punctuation">:</span> applyMyFilter
</code></pre></div><p>In the above example, we expect a relation on the primary model called <strong>myfilter</strong> and a method defined named <strong>scopeApplyMyFilter</strong> on the related model. The second argument contains the second argument will contain the scope definition, including its populated value(s).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">scopeApplyMyFilter</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">,</span> <span class="token variable">$scope</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">whereIn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;my_filter_attribute&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token keyword type-casting">array</span><span class="token punctuation">)</span> <span class="token variable">$scope</span><span class="token operator">-&gt;</span><span class="token property">value</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The <code>modelScope</code> property can also be defined as a static PHP class method (<code>Class::method</code>).</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">myfilter</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> My Filter
    <span class="token key atrule">type</span><span class="token punctuation">:</span> group
    <span class="token key atrule">modelScope</span><span class="token punctuation">:</span> <span class="token string">&quot;App\\MyCustomClass::applyMyFilter&quot;</span>
</code></pre></div><p>In this example, the method should be declared statically on the specified class name.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">App</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">MyCustomClass</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">function</span> <span class="token function-definition function">applyMyFilter</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">,</span> <span class="token variable">$scope</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">whereIn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;my_filter_attribute&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token keyword type-casting">array</span><span class="token punctuation">)</span> <span class="token variable">$scope</span><span class="token operator">-&gt;</span><span class="token property">value</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="scope-dependencies"><a href="#scope-dependencies" class="header-anchor">#</a> Scope Dependencies</h3><p>The <code>dependsOn</code> property allows you to link multiple filters together. When a dependency is modified, the filter scope will reset to allow for new conditions. Take the following example of two scope definitions.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">country</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Country
    <span class="token key atrule">type</span><span class="token punctuation">:</span> group

<span class="token key atrule">state</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> State
    <span class="token key atrule">type</span><span class="token punctuation">:</span> group
    <span class="token key atrule">dependsOn</span><span class="token punctuation">:</span> country
    <span class="token key atrule">optionsMethod</span><span class="token punctuation">:</span> getCityOptionsForFilter
</code></pre></div><p>The state scope depends on the value of the country scope, and the options are filtered in PHP using the <strong>getCityOptionsForFilter</strong> method. The first argument of this method will contain the entire set of scope definitions, including their current values.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getCityOptionsForFilter</span><span class="token punctuation">(</span><span class="token variable">$scopes</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$scopes</span><span class="token operator">-&gt;</span><span class="token property">country</span> <span class="token operator">&amp;&amp;</span> <span class="token punctuation">(</span><span class="token variable">$countryIds</span> <span class="token operator">=</span> <span class="token variable">$scopes</span><span class="token operator">-&gt;</span><span class="token property">country</span><span class="token operator">-&gt;</span><span class="token property">value</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token keyword static-context">self</span><span class="token operator">::</span><span class="token function">whereIn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;country_id&#39;</span><span class="token punctuation">,</span> <span class="token variable">$countryIds</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">lists</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">return</span> <span class="token keyword static-context">self</span><span class="token operator">::</span><span class="token function">lists</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div>`,17))])}const b=l(i,[["render",d]]);export{m as __pageData,b as default};
